import MenuJson from "./menus.json";

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: true,
    };
  },
  created() {},
  methods: {
    clearHistory() {
      this.$router.replace("/shop"); // Replaces current URL in history
    }
  },
};
